from sqlalchemy import Table,Column,String,Integer,Boolean,DateTime,Numeric,ForeignKey,text
from sqlalchemy.dialects.postgresql import UUID,JSONB,CHAR
from app.models import Base
def common():return [Column('id',UUID(as_uuid=True),primary_key=True,server_default=text('gen_random_uuid()')),Column('created_at',DateTime(timezone=True),server_default=text('now()')),Column('updated_at',DateTime(timezone=True),server_default=text('now()')),Column('created_by',UUID(as_uuid=True),ForeignKey('users.id')),Column('updated_by',UUID(as_uuid=True),ForeignKey('users.id')),Column('version',Integer,server_default='1')]
TicketDeparture=type('TicketDeparture',(Base,),{'__table__':Table('ticket_departures',Base.metadata,*common(),Column('owner_user_id',UUID(as_uuid=True)),Column('vehicle_id',UUID(as_uuid=True)),Column('route_label',String),Column('departure_at',DateTime(timezone=True)),Column('vehicle_type',String),Column('air_conditioned',Boolean),Column('fare_per_seat',Numeric),Column('cancellation_policy_snapshot',JSONB),Column('driver_user_id',UUID(as_uuid=True)),Column('status',String))})
TicketSeat=type('TicketSeat',(Base,),{'__table__':Table('ticket_seats',Base.metadata,*common(),Column('departure_id',UUID(as_uuid=True)),Column('seat_number',String),Column('status',String))})
TicketHold=type('TicketHold',(Base,),{'__table__':Table('ticket_holds',Base.metadata,*common(),Column('departure_id',UUID(as_uuid=True)),Column('passenger_user_id',UUID(as_uuid=True)),Column('expires_at',DateTime(timezone=True)),Column('status',String),Column('seat_snapshot',JSONB),Column('quote_snapshot',JSONB))})
TicketReservation=type('TicketReservation',(Base,),{'__table__':Table('ticket_reservations',Base.metadata,*common(),Column('reservation_reference',String),Column('hold_id',UUID(as_uuid=True)),Column('departure_id',UUID(as_uuid=True)),Column('passenger_user_id',UUID(as_uuid=True)),Column('seat_snapshot',JSONB),Column('frozen_snapshot',JSONB),Column('payment_reference',String),Column('payment_status',String),Column('boarding_qr_hash',CHAR),Column('boarding_pin_hash',String),Column('boarding_status',String),Column('cancellation_recorded_at',DateTime(timezone=True)),Column('cancellation_reason',String))})
